#!/usr/bin/env python3
"""Builds js/greatsword.js: the great sword model (owner-made .glb: one mesh with a base colour texture).

usage: python3 tools/build_greatsword.py Greatsword.glb [texture-size] [length-metres]

The .glb has the sword lying along +x (pommel at -x, tip at +x, blade wide along y). It is turned to the way js/rig.js holds weapons (long axis +Y, the grip at the origin, blade wide along x)
and scaled to the given length (default 1.5 m). Output: GREATSWORD = { n, pos, uv, nor, idx, tex } (same packing as the CHAR_MODELS weapons)."""
import sys, os, json, io, base64, struct
import numpy as np
from PIL import Image
HANDLE = 1.3; THIN_W = 0.78; THIN_T = 0.85          # handle length factor, width and thickness factors (the owner asked for a thinner sword and a 1.3x handle)
GT = {5121: np.uint8, 5123: np.uint16, 5125: np.uint32, 5126: np.float32}; NN = {'SCALAR': 1, 'VEC2': 2, 'VEC3': 3}
def main():
    d = open(sys.argv[1], 'rb').read(); cl = struct.unpack('<I', d[12:16])[0]; j = json.loads(d[20:20 + cl]); off = 20 + cl; bl = struct.unpack('<I', d[off:off + 4])[0]; blob = d[off + 8:off + 8 + bl]
    size = int(sys.argv[2]) if len(sys.argv) > 2 else 512; length = float(sys.argv[3]) if len(sys.argv) > 3 else 1.5
    def acc(i):
        a = j['accessors'][i]; bv = j['bufferViews'][a['bufferView']]; n = NN[a['type']]; dt = np.dtype(GT[a['componentType']])
        return np.frombuffer(blob, dt, a['count'] * n, bv.get('byteOffset', 0) + a.get('byteOffset', 0)).reshape(-1, n).astype(np.float64)
    pr = j['meshes'][0]['primitives'][0]; at = pr['attributes']; P = acc(at['POSITION']); N = acc(at['NORMAL']); U = acc(at['TEXCOORD_0']); U[:, 1] = 1 - U[:, 1]; I = acc(pr['indices']).ravel().astype(np.int64)
    # the file holds the sword and, beside it, its scabbard: weld the vertices by position, find the connected parts and keep the one that is the sword (the longest one, with the pommel)
    key = {}; w = np.zeros(len(P), int)
    for i, p in enumerate(map(tuple, np.round(P, 4))): w[i] = key.setdefault(p, len(key))
    par = list(range(len(key)))
    def find(a):
        while par[a] != a: par[a] = par[par[a]]; a = par[a]
        return a
    tri = I.reshape(-1, 3)
    for a, b, c in tri: par[find(w[a])] = find(w[b]); par[find(w[b])] = find(w[c])
    lab = np.array([find(w[i]) for i in range(len(P))]); best = max(np.unique(lab), key=lambda u: np.ptp(P[lab == u, 0]))
    keep = lab == best; tri = tri[keep[tri].all(axis=1)]; used = np.unique(tri); remap = np.full(len(P), -1); remap[used] = np.arange(len(used))
    P, N, U, I = P[used], N[used], U[used], remap[tri].ravel()
    x0, x1 = P[:, 0].min(), P[:, 0].max(); s = length / (x1 - x0); blade = P[:, 0] > 0
    yc = np.median(P[blade, 1]); zc = np.median(P[blade, 2])
    guard = P[P[:, 1] > P[:, 1].min() + 0.8 * np.ptp(P[:, 1]), 0]; xg = guard.min() - 0.01      # where the cross guard starts: the handle is everything below it
    X = P[:, 0].copy(); lo = X < xg; X[lo] = xg - (xg - X[lo]) * HANDLE                          # a longer handle (the pommel moves out, nothing else changes)
    grip = (xg + (xg - (xg - x0) * HANDLE)) / 2                                                 # the hand holds the middle of the handle
    pos = np.stack([-(P[:, 1] - yc) * THIN_W, X - grip, (P[:, 2] - zc) * THIN_T], axis=1) * s    # +x (blade) -> +y, the wide side y -> -x, the thin side z stays z; thinner blade and guard
    nor = np.stack([-N[:, 1], N[:, 0], N[:, 2]], axis=1); nor /= np.maximum(np.linalg.norm(nor, axis=1, keepdims=True), 1e-9)
    mat = j['materials'][0]['pbrMetallicRoughness']; im = j['images'][j['textures'][mat['baseColorTexture']['index']]['source']]; bv = j['bufferViews'][im['bufferView']]
    img = Image.open(io.BytesIO(blob[bv.get('byteOffset', 0):bv.get('byteOffset', 0) + bv['byteLength']])).convert('RGB').resize((size, size), Image.LANCZOS); buf = io.BytesIO(); img.save(buf, 'JPEG', quality=84, optimize=True)
    b64 = lambda a: base64.b64encode(np.ascontiguousarray(a).tobytes()).decode()
    o = {'n': len(pos), 'pos': b64(np.round(pos * 10000).astype(np.int16)), 'uv': b64(np.round(U * 65535).astype(np.uint16)), 'nor': b64(np.round(nor * 127).astype(np.int8)), 'idx': b64(I.astype(np.uint16)), 'tex': 'data:image/jpeg;base64,' + base64.b64encode(buf.getvalue()).decode()}
    js = '// Generated by tools/build_greatsword.py - the great sword model (owner-made). Do not edit by hand.\nconst GREATSWORD = ' + json.dumps(o, separators=(',', ':')) + ';\n'
    open(os.path.join(os.path.dirname(__file__), '..', 'js', 'greatsword.js'), 'w').write(js)
    print('verts', len(pos), 'tris', len(I) // 3, 'tex %d KB' % (len(buf.getvalue()) // 1024), 'js %d KB' % (len(js) // 1024), 'extent', (pos.max(0) - pos.min(0)).round(2))
main()
